window.futvizVista("asistencias-vs-xa","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"asistencias-vs-xa\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"asistencias-vs-xa\"]={\"id\":\"asistencias-vs-xa\",\"titulo\":\"Asistencias vs. xA\",\"tabla\":\"jugadores\",\"entidad\":\"jugadores\",\"x\":{\"col\":\"xA\",\"label\":\"xA\",\"corto\":\"xA\",\"dec\":1,\"decLista\":2},\"y\":{\"col\":\"a\",\"label\":\"Asistencias\",\"corto\":\"Asist.\",\"dec\":0},\"referencia\":{\"tipo\":\"diagonal\",\"dif\":\"asistencias \u2212 xA\",\"sobre\":\"Sobrerrendimiento\",\"bajo\":\"Bajo rendimiento\"},\"requiere\":[\"xA\",\"a\"],\"subtitulo\":\"\u00bfQui\u00e9n sobre/bajo-rindi\u00f3 su expected assists? Jugadores con \u2265{min} min \u00b7 {temporada}\",\"filtros\":{\"posicion\":true,\"nivel\":true,\"sub21\":true},\"metricas\":[{\"id\":\"dif\",\"etiqueta\":\"Diferencia\",\"ayuda\":\"Los que m\u00e1s se alejan de la diagonal (asistencias \u2212 xA)\"},{\"id\":\"x\",\"etiqueta\":\"xA\",\"ayuda\":\"Los de mayor xA\"},{\"id\":\"y\",\"etiqueta\":\"Asist.\",\"ayuda\":\"Los de mayor Asistencias\"}],\"queMirar\":\"Mismo esquema que el de goles pero para crear: la diagonal es \\\"asisti\u00f3 lo que sus pases merec\u00edan\\\". Por encima, jugadores cuyos compa\u00f1eros definieron bien lo que les pusieron.\",\"porQue\":\"El xA mide la calidad de los pases de gol que dio un jugador: **cu\u00e1nta probabilidad de gol gener\u00f3 el remate que habilit\u00f3**. Correlaciona 0.85 con las asistencias reales.\\n\\nLa diferencia clave con el gr\u00e1fico de goles: ac\u00e1 el que est\u00e1 por encima de la diagonal **no hizo nada distinto**. Una asistencia depende de que otro la meta, as\u00ed que estar arriba dice sobre todo que quien remat\u00f3 estuvo acertado. Es todav\u00eda menos atribuible al jugador que la diferencia entre goles y xG, y por eso conviene leerlo como una medida de creaci\u00f3n de ocasiones (el eje horizontal) m\u00e1s que de rendimiento sobre lo esperado.\",\"insight\":\"asist_xa\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\",\"rendimiento\"]};</script>");